def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    last_me, last_opp = history[-1]

    opp_total_d = 0
    my_total_d = 0
    for m, o in history:
        if o == 'D':
            opp_total_d += 1
        if m == 'D':
            my_total_d += 1

    r5d = 0
    r10d = 0
    r20d = 0
    r5my = 0
    r20my = 0

    for m, o in history[-5:]:
        if o == 'D':
            r5d += 1
        if m == 'D':
            r5my += 1

    for m, o in history[-10:]:
        if o == 'D':
            r10d += 1

    for m, o in history[-20:]:
        if o == 'D':
            r20d += 1
        if m == 'D':
            r20my += 1

    forgave = 0
    punished = 0
    for i in range(n - 1):
        if history[i][0] == 'D':
            if history[i + 1][1] == 'C':
                forgave += 1
            else:
                punished += 1

    opp_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_streak += 1
        else:
            break

    my_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][0] == 'D':
            my_streak += 1
        else:
            break

    malicious = (
        opp_total_d * 100 > n * 35 or
        r10d >= 6 or
        r5d >= 3 or
        opp_streak >= 3
    )

    opp_good = (
        opp_total_d <= max(3, n // 12) and
        r5d == 0 and
        r10d == 0 and
        r20d <= 1
    )

    my_safe = (
        my_total_d * 100 <= n * 30 and
        r5my <= 2 and
        r20my <= 12 and
        my_streak <= 2
    )

    exploit_ok = (
        opp_good and
        my_safe and
        forgave > punished and
        forgave >= 1 and
        not malicious and
        last_opp == 'C'
    )

    test_due = (
        n >= 85 and
        forgave == 0 and
        punished == 0 and
        last_me != 'D' and
        not malicious and
        opp_total_d <= 3 and
        r5d == 0 and
        r10d == 0 and
        my_total_d <= 3
    )

    if exploit_ok:
        return 'D'

    if malicious:
        return 'D'

    if test_due:
        return 'D'

    if last_opp == 'D':
        if last_me == 'D':
            if opp_total_d * 100 <= n * 40 and r5d <= 2:
                return 'C'
            return 'D'

        if r5d >= 2:
            return 'D'

        if opp_total_d * 100 <= n * 30:
            return 'C'

        return 'D'

    return 'C'
